import { notFound } from 'next/navigation';
import { Post, Comment } from '../../types';
import BackButton from '../../components/BackButton';
import type { Metadata } from 'next';

interface Props {
  params: Promise<{ id: string }>;
}

export async function generateStaticParams() {
  const posts: Post[] = await fetch('https://jsonplaceholder.typicode.com/posts').then((res) =>
    res.json()
  );

  return posts.slice(0, 10).map((post) => ({
    id: post.id.toString(),
  }));
}

export async function generateMetadata({ params }: Props): Promise<Metadata> {
  const { id } = await params;
  const post: Post = await fetch(`https://jsonplaceholder.typicode.com/posts/${id}`).then((res) =>
    res.json()
  ).catch(() => null);

  if (!post) {
    return {
      title: 'Post Not Found - My Blog',
    };
  }

  return {
    title: `${post.title} - My Blog`,
    description: post.body.substring(0, 160),
    openGraph: {
      title: post.title,
      description: post.body.substring(0, 160),
    },
  };
}

async function getPost(id: string): Promise<{ post: Post; comments: Comment[] } | null> {
  try {
    const [post, comments] = await Promise.all([
      fetch(`https://jsonplaceholder.typicode.com/posts/${id}`, { next: { revalidate: 300 } }).then(res => {
        if (!res.ok) throw new Error('Failed to fetch post');
        return res.json();
      }),
      fetch(`https://jsonplaceholder.typicode.com/posts/${id}/comments`, { next: { revalidate: 300 } }).then(res => {
        if (!res.ok) throw new Error('Failed to fetch comments');
        return res.json();
      })
    ]);
    return { post, comments };
  } catch (error) {
    return null;
  }
}

export default async function BlogPost({ params }: Props) {
  const { id } = await params;
  const data = await getPost(id);

  if (!data) {
    notFound();
  }

  const { post, comments } = data;

  return (
    <article>
      <BackButton />

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  );
}

import { NextResponse } from 'next/server';

export async function GET() {
  // Simulate fetching posts
  const posts = [
    { id: 1, title: 'First Post', content: 'This is the first post' },
    { id: 2, title: 'Second Post', content: 'This is the second post' }
  ];

  return NextResponse.json(posts);
}

export async function POST(request: Request) {
  const body = await request.json();
  const { title, content } = body;

  if (!title || !content) {
    return NextResponse.json({ error: 'Title and content are required' }, { status: 400 });
  }

  // Simulate creating a post
  const newPost = {
    id: Date.now(),
    title,
    content,
    createdAt: new Date().toISOString()
  };

  return NextResponse.json(newPost, { status: 201 });
}

import { NextResponse } from 'next/server';

export async function GET(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  const { id } = await params;

  // Simulate fetching a single post
  const post = {
    id: parseInt(id),
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString()
  };

  return NextResponse.json(post);
}

export async function PUT(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  const { id } = await params;
  const body = await request.json();
  const { title, content } = body;

  // Simulate updating a post
  const updatedPost = {
    id: parseInt(id),
    title: title || `Post ${id}`,
    content: content || `Updated content for post ${id}`,
    updatedAt: new Date().toISOString()
  };

  return NextResponse.json(updatedPost);
}

export async function DELETE(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  const { id } = await params;

  // Simulate deleting a post
  return NextResponse.json({ message: `Post ${id} deleted successfully` });
}

